assignments.referenceSolution:
A falsy `room_type` short-circuits to "all rooms"; otherwise the string is mapped to the enum (raising `KeyError` for an unknown name) and the repository filters. The controller wraps the call and returns an empty list with `FAILURE` on error.

**`services/room_service.py`**

```python
from abc import ABC, abstractmethod
from typing import List
from models.room import Room

class RoomService(ABC):
    @abstractmethod
    def get_rooms(self, room_type: str) -> List[Room]:
        pass
```

**`services/room_service_impl.py`**

```python
from typing import List
from models.room import Room
from models.room_type import RoomType
from services.room_service import RoomService
from repositories.room_repository import RoomRepository

class RoomServiceImpl(RoomService):
    def __init__(self, room_repo: RoomRepository):
        self.room_repo = room_repo

    def get_rooms(self, room_type_str: str) -> List[Room]:
        if not room_type_str:
            return self.room_repo.get_rooms()

        # Parse the string into the RoomType Enum. This will raise a KeyError if invalid.
        mapped_room_type = RoomType[room_type_str.upper()]

        return self.room_repo.get_rooms_by_room_type(mapped_room_type)
```

**`controllers/room_controller.py`**

```python
from dtos.get_rooms_request_dto import GetRoomsRequestDto
from dtos.get_rooms_response_dto import GetRoomsResponseDto
from dtos.response_status import ResponseStatus
from services.room_service import RoomService

class RoomController:
    def __init__(self, room_service: RoomService):
        self.room_service = room_service

    def get_rooms(self, request_dto: GetRoomsRequestDto) -> GetRoomsResponseDto:
        response = GetRoomsResponseDto()
        try:
            rooms = self.room_service.get_rooms(request_dto.room_type)
            response.rooms = rooms
            response.response_status = ResponseStatus.SUCCESS
        except Exception:
            response.rooms = []
            response.response_status = ResponseStatus.FAILURE

        return response
```

